/**
 * Typed failures for the Office tools.
 *
 * Every code is stable and model-facing: the model can tell "this is a legacy
 * .doc, save it as .docx" (OFFICE_UNSUPPORTED) from "the archive is corrupt"
 * (OFFICE_BAD_ZIP) from "the sandbox said no" (OFFICE_SANDBOX_DENIED), which
 * is the difference between a useful retry and a dead end.
 */

import { HarnessError } from "@deepseek-ai/dsh-llm";

export class OfficeError extends HarnessError {
	constructor(message, code) {
		super(message);
		this.name = "OfficeError";
		this.code = code;
	}
}
